import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.BUwdTBzS.js";const g=JSON.parse('{"title":"design-advisor","description":"方案分析与避坑指南。编码前的\\"大脑\\"——帮助正确分析问题、设计方案、规避已知错误模式。包含设计指南、样式分析、反模式清单三大模块。可被 dev-flow 步骤 3（制定方案）按需调用，也可独立使用。","frontmatter":{"title":"design-advisor","description":"方案分析与避坑指南。编码前的\\"大脑\\"——帮助正确分析问题、设计方案、规避已知错误模式。包含设计指南、样式分析、反模式清单三大模块。可被 dev-flow 步骤 3（制定方案）按需调用，也可独立使用。"},"headers":[],"relativePath":"skills/design-advisor.md","filePath":"skills/design-advisor.md","lastUpdated":null}'),s={name:"skills/design-advisor.md"};function r(i,t,l,n,c,u){return d(),a("div",null,[...t[0]||(t[0]=[o('<blockquote><p>📄 本页由源文件 <code>skills/design-advisor/SKILL.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="design-advisor" tabindex="-1">design-advisor <a class="header-anchor" href="#design-advisor" aria-label="Permalink to &quot;design-advisor&quot;">​</a></h1><blockquote><p><strong>定位</strong>：编码前的&quot;大脑&quot;——帮助正确分析问题、设计方案、规避已知错误模式。 可被 <code>dev-flow</code> 步骤 3（制定方案）按需调用，也可独立使用。</p></blockquote><hr><h2 id="全局输出规范-最高优先级" tabindex="-1">全局输出规范（最高优先级） <a class="header-anchor" href="#全局输出规范-最高优先级" aria-label="Permalink to &quot;全局输出规范（最高优先级）&quot;">​</a></h2><blockquote><p>本 Skill 生成的方案分析、样式诊断、反模式建议中，<strong>文件路径、代码位置引用</strong>必须遵循 <code>~/.codebuddy/rules/AI行为规范.mdc</code> 的「文件/代码位置引用」规范（反引号包裹相对路径 <code>`相对路径`</code> + 空格后缀行号 <code>L行号</code>，IDE 自动识别为可点击链接）。</p><p><strong>适用范围</strong>：方案设计中引用的代码文件、样式分析中的 SCSS/CSS 文件、反模式清单中引用的示例代码位置等所有输出。</p></blockquote><h2 id="路由规则" tabindex="-1">路由规则 <a class="header-anchor" href="#路由规则" aria-label="Permalink to &quot;路由规则&quot;">​</a></h2><p>收到请求后，根据用户意图匹配下表，使用 <code>read_file</code> 加载对应子模块（相对于本 Skill 目录）：</p><table tabindex="0"><thead><tr><th>意图关键词</th><th>目标模块</th><th>加载指令</th></tr></thead><tbody><tr><td>方案设计 / 评估方案 / 制定方案 / 分析问题 / 排查问题 / 定位根因</td><td><strong>设计指南</strong></td><td><code>read_file(&quot;modules/design-guide.md&quot;)</code></td></tr><tr><td>样式分析 / CSS调试 / 内联样式 / 主题系统 / scss</td><td><strong>样式分析</strong></td><td><code>read_file(&quot;modules/style-analysis.md&quot;)</code></td></tr><tr><td>反模式 / 避坑 / 常见错误 / 踩坑 / 经验教训 / 反例</td><td><strong>反模式清单</strong></td><td><code>read_file(&quot;modules/anti-patterns.md&quot;)</code></td></tr></tbody></table><h3 id="加载策略" tabindex="-1">加载策略 <a class="header-anchor" href="#加载策略" aria-label="Permalink to &quot;加载策略&quot;">​</a></h3><ul><li><strong>单一意图</strong>：只加载匹配的一个模块。</li><li><strong>多模块场景</strong>：用户意图涉及多个模块时，按需依次加载。例如「帮我分析这个样式问题的方案」→ 先加载设计指南，再加载样式分析。</li><li><strong>dev-flow 调用时</strong>：dev-flow 步骤 3 会在 <code>use_skill</code> 调用中指定路由目标（如「路由到 design-guide 模块」），直接执行对应的 <code>read_file</code> 加载。</li><li><strong>不确定时</strong>：默认加载设计指南（design-guide），它是最通用的模块。</li></ul><hr><h2 id="模块概览-仅供路由判断-不展开详情" tabindex="-1">模块概览（仅供路由判断，不展开详情） <a class="header-anchor" href="#模块概览-仅供路由判断-不展开详情" aria-label="Permalink to &quot;模块概览（仅供路由判断，不展开详情）&quot;">​</a></h2><h3 id="设计指南-design-guide" tabindex="-1">设计指南（design-guide） <a class="header-anchor" href="#设计指南-design-guide" aria-label="Permalink to &quot;设计指南（design-guide）&quot;">​</a></h3><p>方案设计的核心方法论：追根因、复用已有逻辑、隔离影响范围、对比参照、JS/CSS 断点分析、边界情况处理、问题排查原则、第三方库源码确认。</p><h3 id="样式分析-style-analysis" tabindex="-1">样式分析（style-analysis） <a class="header-anchor" href="#样式分析-style-analysis" aria-label="Permalink to &quot;样式分析（style-analysis）&quot;">​</a></h3><p>样式来源分析规范：CSS vs JS 内联样式识别、内联样式覆盖策略、<code>.scss</code> vs <code>.module.scss</code> 差异、主题系统、对比参照修复原则。</p><h3 id="反模式清单-anti-patterns" tabindex="-1">反模式清单（anti-patterns） <a class="header-anchor" href="#反模式清单-anti-patterns" aria-label="Permalink to &quot;反模式清单（anti-patterns）&quot;">​</a></h3><p>已发生过的 9 个错误模式及正确做法：反复调参、影响范围失控、自创等价逻辑、跳过根因分析、改动范围越界、误解用户指令、优化范围失控、JS/CSS 断点不一致、优化破坏 DOM 时序。</p><hr><h2 id="独立使用" tabindex="-1">独立使用 <a class="header-anchor" href="#独立使用" aria-label="Permalink to &quot;独立使用&quot;">​</a></h2><p>不依赖 dev-flow，可直接触发：</p><table tabindex="0"><thead><tr><th>用户说</th><th>AI 行为</th></tr></thead><tbody><tr><td>&quot;帮我分析下这个方案&quot;</td><td><code>read_file</code> 加载 design-guide 模块</td></tr><tr><td>&quot;这个样式为什么不对&quot;</td><td><code>read_file</code> 加载 style-analysis 模块</td></tr><tr><td>&quot;有没有什么反模式要注意&quot;</td><td><code>read_file</code> 加载 anti-patterns 模块</td></tr><tr><td>&quot;评估下这个修改方案&quot;</td><td><code>read_file</code> 加载 design-guide 模块</td></tr><tr><td>&quot;分析下这个样式问题的方案&quot;</td><td><code>read_file</code> 依次加载 design-guide + style-analysis</td></tr><tr><td>&quot;帮我避坑&quot;</td><td><code>read_file</code> 加载 anti-patterns 模块</td></tr></tbody></table>',23)])])}const q=e(s,[["render",r]]);export{g as __pageData,q as default};
